int _unitLocalEstimateSize(
  UnitLocal object,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  var bytesCount = offsets.last;
  bytesCount += 3 + object.descriptionJson.length * 3;
  {
    final value = object.localPdfPath;
    if (value != null) {
      bytesCount += 3 + value.length * 3;
    }
  }
  bytesCount += 3 + object.subjectUuid.length * 3;
  bytesCount += 3 + object.textbookPdfSizeJson.length * 3;
  bytesCount += 3 + object.textbookPdfUrlJson.length * 3;
  bytesCount += 3 + object.titleJson.length * 3;
  bytesCount += 3 + object.uuid.length * 3;
  return bytesCount;
}

