  Map<Type, List<int>> allOffsets,
) {
  writer.writeString(offsets[0], object.descriptionJson);
  writer.writeBool(offsets[1], object.isDeleted);
  writer.writeBool(offsets[2], object.isDirty);
  writer.writeBool(offsets[3], object.isDownloaded);
  writer.writeString(offsets[4], object.localPdfPath);
  writer.writeLong(offsets[5], object.sequenceNumber);
  writer.writeString(offsets[6], object.subjectUuid);
  writer.writeString(offsets[7], object.textbookPdfSizeJson);
  writer.writeString(offsets[8], object.textbookPdfUrlJson);
  writer.writeString(offsets[9], object.titleJson);
  writer.writeDateTime(offsets[10], object.updatedAt);
  writer.writeString(offsets[11], object.uuid);
}

